class Solution {
    public int smallestRangeII(int[] nums,int k){
        Arrays.sort(nums);
        int answer=nums[nums.length-1]-nums[0];
        for(int i=0;i+1<nums.length;i++){
            int high=Math.max(nums[nums.length-1]-k,nums[i]+k),low=Math.min(nums[0]+k,nums[i+1]-k);
            answer=Math.min(answer,high-low);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun smallestRangeII(nums:IntArray,k:Int):Int{
        nums.sort();
        var answer=nums.last()-nums.first();
        for(i in 0 until nums.lastIndex){
            val high=maxOf(nums.last()-k,nums[i]+k);
            val low=minOf(nums.first()+k,nums[i+1]-k);
            answer=minOf(answer,high-low)
        };
        return answer
    }
}

